export type PurgedIssue = {
  readonly commentIds: readonly string[];
  /** Megabytes the issue's attachments were counted for, each rounded up. */
  readonly storageMb: number;
};

const BYTES_PER_MB = 1024 * 1024;

/**
 * Permanently deletes one issue with its label links, comments and
 * attachments in a single transaction, first recording its number so the
 * project never hands it out again.
 */
export async function purgeIssue(
  orgId: OrgId,
  issueId: IssueId,
): Promise<PurgedIssue | null> {
  return getDb().transaction((tx) => {
    const issue = tx
      .select()
      .from(issues)
      .where(and(orgPredicate(issues.orgId, orgId), eq(issues.id, issueId)))
      .get();
    if (!issue) return null;

