import { afterAll, beforeAll, expect, it, vi } from "vitest";
vi.mock("@/lib/logger", async () => (await import("./_support/doubles/misc")).loggerModule);
import { runCleanupArchivedJob } from "@/server/jobs/cleanup-archived-job";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as attachmentRepo from "@/server/repositories/attachment-repository";
import * as usageRepo from "@/server/repositories/usage-repository";
import * as issueService from "@/server/services/issue-service";
import { RestoreRefusedError } from "@/lib/soft-delete";
import { createTenant, issueInput, useTemporaryDatabase } from "./_support/fixtures";
import { getDb, issues } from "@/server/db";
import { eq } from "drizzle-orm";

let cleanup: () => void;
beforeAll(async () => { cleanup = await useTemporaryDatabase(); });
afterAll(() => cleanup());

it("restores and purges", async () => {
  const t = await createTenant("tmp", "free");
  const a = t.actors.owner;
  const i1 = await issueService.createIssue(a, issueInput(t.org.id, t.project.id, { title: "one" }));
  await expect(issueService.restoreIssue(a, t.org.id, i1.id)).rejects.toMatchObject({ reason: "not_archived" });
  await issueService.archiveIssue(a, t.org.id, i1.id);
  const r = await issueService.restoreIssue(a, t.org.id, i1.id);
  expect(r.number).toBe(i1.number);
  await issueService.archiveIssue(a, t.org.id, i1.id);
  await attachmentRepo.insertAttachment({ orgId: t.org.id, issueId: i1.id, filename: "f", contentType: "x", sizeBytes: 1500000 } as never, a.userId);
  await usageRepo.recomputeUsage(t.org.id);
  await usageRepo.incrementUsage(t.org.id, { storageMbUsed: 2 });
  getDb().update(issues).set({ archivedAt: "2026-01-01T00:00:00.000Z" }).where(eq(issues.id, i1.id)).run();
  await expect(issueService.restoreIssue(a, t.org.id, i1.id)).rejects.toBeInstanceOf(RestoreRefusedError);
  const res = await runCleanupArchivedJob(new Date());
  expect(res.processed).toBeGreaterThan(0);
  await expect(issueService.restoreIssue(a, t.org.id, i1.id)).rejects.toMatchObject({ code: "not_found" });
  expect((await usageRepo.getUsage(t.org.id)).storageMbUsed).toBe(0);
  expect(await issueRepo.nextIssueNumber(t.org.id, t.project.id)).toBe(i1.number + 1);
});
EOF
